<tr class='{$data['rowclass']}'><td class='altrow' style=\"width:1%\" align='center'>{$data['rank']}</td><td style=\"width:20%\" align='center'><a href='" . $this->registry->getClass('output')->formatUrl( $this->registry->getClass('output')->buildUrl( "app=reviews&amp;module=products&amp;section=categories&amp;do=viewcat&amp;cid={$data['cparent']}", "public",'' ), "{$data['fname2']}", "showrevcategorytwo" ) . "'>{$data['pcname']}</a></td><td class='altrow' style=\"width:48%\"><strong><a href='" . $this->registry->getClass('output')->formatUrl( $this->registry->getClass('output')->buildUrl( "app=reviews&amp;module=products&amp;section=products&amp;do=products&amp;id={$data['cid']}", "public",'' ), "{$data['fname']}", "showrevproduct" ) . "'>{$data['cname']}</a></strong> ({$data['count']} {$this->lang->words['viewall2']})<br />{$this->lang->words['lastreview']}{$data['date']}</td><td style=\"width:1%\" align='center'>{$data['views']}</td><td class='altrow' style=\"width:10%\" align='center'>{$data['finaloverall']}</td><td style=\"width:10%\" align='center'>{$data['gtoverall']}</td><td class='altrow' style=\"width:10%\" align='center'>{$data['myoverall']}</td></tr>
") : ("
<tr class='{$data['rowclass']}'><td class='altrow' style=\"width:1%\" align='center'>{$data['rank']}</td><td style=\"width:20%\" align='center'><a href='" . $this->registry->getClass('output')->formatUrl( $this->registry->getClass('output')->buildUrl( "app=reviews&amp;module=products&amp;section=categories&amp;do=viewcat&amp;cid={$data['cparent']}", "public",'' ), "{$data['fname2']}", "showrevcategorytwo" ) . "'>{$data['pcname']}</a></td><td class='altrow' style=\"width:58%\"><strong><a href='" . $this->registry->getClass('output')->formatUrl( $this->registry->getClass('output')->buildUrl( "app=reviews&amp;module=products&amp;section=products&amp;do=products&amp;id={$data['cid']}", "public",'' ), "{$data['fname']}", "showrevproduct" ) . "'>{$data['cname']}</a></strong> ({$data['count']} {$this->lang->words['viewall2']})<br />{$this->lang->words['lastreview']}{$data['date']}</td><td style=\"width:1%\" align='center'>{$data['views']}</td><td class='altrow' style=\"width:10%\" align='center'>{$data['finaloverall']}</td><td style=\"width:10%\" align='center'>{$data['myoverall']}</td></tr>
")) . "";
return $IPBHTML;
